import React from 'react'
import { Link } from 'react-router-dom'
export default function Navbar() {
  const user = JSON.parse(localStorage.getItem('authUser') || 'null')

  return (
    <div>
    <nav className='navbar'>
         <Link className="brand" to="/">EthioNexa</Link>
        <div className='links'>
             <Link to ="/">Home</Link>
        {user ? <Link className='nav-cta' to="/dashboard">Dashboard</Link> : <Link className='nav-cta' to="/login">Login / Sign up</Link>}
        </div>
    </nav>
    </div>
  )
}
